static float clip(float value, float lower, float upper)
{
    if (value < lower) return lower;
    if (value > upper) return upper;
    return value;
}

static float elu(float value)
{
    return value >= 0.0f ? value : expf(value) - 1.0f;
}

static void linear_elu(
    const float *input, size_t input_size, float *output, size_t output_size,
    const float *weight, const float *bias)
{
    size_t row;
    size_t column;
    for (row = 0; row < output_size; ++row) {
        float sum = bias[row];
        const float *row_weight = weight + row * input_size;
        for (column = 0; column < input_size; ++column) {
            sum += row_weight[column] * input[column];
        }
        output[row] = elu(sum);
    }
}

void g1_assist_v2_v2_history_reset(
    G1AssistV2V2History *history,
    const float initial_position_rad[2],
    const float initial_velocity_rad_s[2])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || initial_position_rad == NULL || initial_velocity_rad_s == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V2_V2_HISTORY_LENGTH; ++frame) {
        for (side = 0; side < 2; ++side) {
            history->position_rad[frame][side] = initial_position_rad[side];
            history->velocity_rad_s[frame][side] = initial_velocity_rad_s[side];
            history->smoothed_torque_nm[frame][side] = 0.0f;
        }
    }
    history->next_index = 0U;
}

void g1_assist_v2_v2_history_append(
    G1AssistV2V2History *history,
    const float position_rad[2],
    const float velocity_rad_s[2],
    const float previous_smoothed_torque_nm[2])
{
    unsigned int side;
    unsigned int index;
    if (history == NULL || position_rad == NULL || velocity_rad_s == NULL || previous_smoothed_torque_nm == NULL) return;
    index = history->next_index;
    for (side = 0; side < 2; ++side) {
        history->position_rad[index][side] = position_rad[side];
        history->velocity_rad_s[index][side] = velocity_rad_s[side];
        history->smoothed_torque_nm[index][side] = previous_smoothed_torque_nm[side];
    }
    history->next_index = (index + 1U) % G1_ASSIST_V2_V2_HISTORY_LENGTH;
}

void g1_assist_v2_v2_history_build_observation(
    const G1AssistV2V2History *history,
    float observation[G1_ASSIST_V2_V2_INPUT_SIZE])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || observation == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V2_V2_HISTORY_LENGTH; ++frame) {
        unsigned int source = (history->next_index + frame) % G1_ASSIST_V2_V2_HISTORY_LENGTH;
        for (side = 0; side < 2; ++side) {
            observation[frame * 2U + side] = history->position_rad[source][side];
            observation[50U + frame * 2U + side] = history->velocity_rad_s[source][side];
            observation[100U + frame * 2U + side] = history->smoothed_torque_nm[source][side];
        }
    }
}

void g1_assist_v2_v2_policy_forward(
    const float observation[G1_ASSIST_V2_V2_INPUT_SIZE],
    float action[G1_ASSIST_V2_V2_OUTPUT_SIZE],
    G1AssistV2V2Workspace *workspace)
{
    size_t index;
    size_t row;
    size_t column;
    if (observation == NULL || action == NULL || workspace == NULL) return;
    for (index = 0; index < G1_ASSIST_V2_V2_INPUT_SIZE; ++index) {
        workspace->secondary_150[index] =
            (observation[index] - OBS_MEAN[index]) / (OBS_STD[index] + NORMALIZER_EPS);
    }
    linear_elu(workspace->secondary_150, 150, workspace->hidden_256, 256, WEIGHT_0, BIAS_0);
    linear_elu(workspace->hidden_256, 256, workspace->secondary_150, 64, WEIGHT_1, BIAS_1);
    linear_elu(workspace->secondary_150, 64, workspace->hidden_256, 16, WEIGHT_2, BIAS_2);
    for (row = 0; row < G1_ASSIST_V2_V2_OUTPUT_SIZE; ++row) {
        float sum = BIAS_3[row];
        const float *row_weight = WEIGHT_3 + row * 16U;
        for (column = 0; column < 16; ++column) sum += row_weight[column] * workspace->hidden_256[column];
        action[row] = sum;
    }
}


static int finite_pair(const float *x)
{
    return x != NULL && isfinite(x[0]) && isfinite(x[1]);
}
void g1_assist_v2_v2_stop(G1AssistV2V2Controller *c, float out[2])
{
    if (out != NULL) out[0] = out[1] = 0.0f;
    if (c == NULL) return;
    c->ready = 0U;
    c->previous[0] = c->previous[1] = 0.0f;
    c->filtered_velocity[0] = c->filtered_velocity[1] = 0.0f;
}
int g1_assist_v2_v2_reset(G1AssistV2V2Controller *c, const float p[2], const float v[2], float scale)
{
    if (c == NULL) return -1;
    g1_assist_v2_v2_stop(c, NULL);
    if (!finite_pair(p) || !finite_pair(v) || !isfinite(scale) || scale < 0 || scale > 1) return -1;
    g1_assist_v2_v2_history_reset(&c->history, p, v);
    c->output_scale = scale;
    c->first = 1U;
    c->ready = 1U;
    return 0;
}
int g1_assist_v2_v2_step(G1AssistV2V2Controller *c, const float p[2], const float v[2], int enabled, float out[2])
{
    float action[2];
    size_t side;
    if (c == NULL || out == NULL) {
        g1_assist_v2_v2_stop(c, out);
        return -1;
    }
    out[0] = out[1] = 0;
    if (!enabled || !c->ready) {
        g1_assist_v2_v2_stop(c, out);
        return 1;
    }
    if (!finite_pair(p) || !finite_pair(v) || !isfinite(c->output_scale) ||
        c->output_scale < 0 || c->output_scale > 1) {
        g1_assist_v2_v2_stop(c, out);
        return -1;
    }
    if (!c->first) g1_assist_v2_v2_history_append(&c->history, p, v, c->previous);
    c->first = 0U;
    g1_assist_v2_v2_history_build_observation(&c->history, c->observation);
    g1_assist_v2_v2_policy_forward(c->observation, action, &c->workspace);
    if (!finite_pair(action)) {
        g1_assist_v2_v2_stop(c, out);
        return -1;
    }
    for (side = 0; side < 2; ++side) {
        float phase, gate, a, target, delta, limit;
        c->filtered_velocity[side] += (1.0f - expf(-0.01f/0.05f)) * (v[side] - c->filtered_velocity[side]);
        phase = clip((fabsf(c->filtered_velocity[side]) - 0.15f)/0.65f, 0, 1);
        gate = phase * phase * (3 - 2 * phase);
        a = clip(action[side], -1, 1);
        target = a * (a < 0 ? 10.0f : 4.0f) * gate;
        delta = target - c->previous[side];
        limit = delta < 0 ? 0.8f : 0.4f;
        c->previous[side] += clip(delta, -limit, limit);
        out[side] = clip(c->output_scale * c->previous[side], -8.0f, 4.0f);
    }
    return 0;
}

